// Step 2: Write minimal implementation to pass tests
function add(numbers) {
    if (numbers === '') return 0;

    const nums = numbers
        .split(/[,\n]/)
        .map(n => parseInt(n, 10));

    return nums.reduce((sum, n) => sum + n, 0);
}

