@pytest.mark.benchmark
def test_fibonacci_performance(benchmark):
    def fibonacci(n):
        if n <= 1:
            return n
        return fibonacci(n-1) + fibonacci(n-2)

    result = benchmark(fibonacci, 20)
    assert result == 6765

