# Run with: locust -f tests/load/locustfile.py --host=http://localhost:8000

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const errorRate = new Rate('errors');

export const options = {
    stages: [
        { duration: '30s', target: 20 },  // Ramp up to 20 users
        { duration: '1m', target: 50 },   // Stay at 50 users
        { duration: '30s', target: 0 },   // Ramp down
    ],
    thresholds: {
        http_req_duration: ['p(95)<500'], // 95% of requests must complete below 500ms
        errors: ['rate<0.1'],             // Error rate must be below 10%
    },
};

export default function() {
    const url = 'http://localhost:3000/api/users';

    const payload = JSON.stringify({
        name: 'Test User',
        email: `test${__VU}@example.com`
    });

    const params = {
        headers: { 'Content-Type': 'application/json' },
    };

    const response = http.post(url, payload, params);

    const success = check(response, {
        'status is 201': (r) => r.status === 201,
        'response has id': (r) => r.json('id') !== undefined,
    });

    errorRate.add(!success);
    sleep(1);
}

def quicksort(arr):
    """Quicksort implementation with Lomuto partition scheme"""
    if len(arr) <= 1:
        return arr

    def partition(low, high):
        pivot = arr[high]
        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quicksort_helper(low, high):
        if low < high:
            pi = partition(low, high)
            quicksort_helper(low, pi - 1)
            quicksort_helper(pi + 1, high)

    quicksort_helper(0, len(arr) - 1)
    return arr

function mergeSort(arr) {
    // Base case: arrays with 0 or 1 element are sorted
    if (arr.length <= 1) return arr;

    const mid = Math.floor(arr.length / 2);
    const left = mergeSort(arr.slice(0, mid));
    const right = mergeSort(arr.slice(mid));

    // Merge two sorted arrays
    function merge(left, right) {
        const result = [];
        let i = 0, j = 0;

        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                result.push(left[i++]);
            } else {
                result.push(right[j++]);
            }
        }

        return result.concat(left.slice(i)).concat(right.slice(j));
    }

    return merge(left, right);
}

