struct HuffmanNode {
    char data;
    int freq;
    HuffmanNode *left, *right;

    HuffmanNode(char data, int freq) : data(data), freq(freq), left(nullptr), right(nullptr) {}
};

struct Compare {
    bool operator()(HuffmanNode* l, HuffmanNode* r) {
        return l->freq > r->freq;
    }
};

class HuffmanCoding {
public:
    unordered_map<char, string> encode(const string& text) {
        // Calculate frequencies
        unordered_map<char, int> freq;
        for (char c : text) freq[c]++;

        // Create priority queue
        priority_queue<HuffmanNode*, vector<HuffmanNode*>, Compare> pq;
        for (auto& p : freq) {
            pq.push(new HuffmanNode(p.first, p.second));
        }

        // Build Huffman tree
        while (pq.size() > 1) {
            HuffmanNode* left = pq.top(); pq.pop();
            HuffmanNode* right = pq.top(); pq.pop();

            HuffmanNode* parent = new HuffmanNode('$', left->freq + right->freq);
            parent->left = left;
            parent->right = right;
            pq.push(parent);
        }

        // Generate codes
        unordered_map<char, string> codes;
        generateCodes(pq.top(), "", codes);
        return codes;
    }

private:
    void generateCodes(HuffmanNode* root, string code, unordered_map<char, string>& codes) {
        if (!root) return;
        if (root->data != '$') codes[root->data] = code;
        generateCodes(root->left, code + "0", codes);
        generateCodes(root->right, code + "1", codes);
    }
};

function activitySelection(start, finish) {
    // Activities sorted by finish time
    const activities = start.map((s, i) => ({ start: s, finish: finish[i], index: i }));
    activities.sort((a, b) => a.finish - b.finish);

    const selected = [activities[0].index];
    let lastFinish = activities[0].finish;

    for (let i = 1; i < activities.length; i++) {
        if (activities[i].start >= lastFinish) {
            selected.push(activities[i].index);
            lastFinish = activities[i].finish;
        }
    }

    return selected;
}

class UnionFind {
    constructor(size) {
        this.parent = Array.from({ length: size }, (_, i) => i);
        this.rank = Array(size).fill(0);
    }

    find(x) {
        if (this.parent[x] !== x) {
            this.parent[x] = this.find(this.parent[x]); // Path compression
        }
        return this.parent[x];
    }

    union(x, y) {
        const rootX = this.find(x);
        const rootY = this.find(y);

        if (rootX === rootY) return false;

        // Union by rank
        if (this.rank[rootX] < this.rank[rootY]) {
            this.parent[rootX] = rootY;
        } else if (this.rank[rootX] > this.rank[rootY]) {
            this.parent[rootY] = rootX;
        } else {
            this.parent[rootY] = rootX;
            this.rank[rootX]++;
        }
        return true;
    }
}

function kruskalMST(n, edges) {
    // Sort edges by weight
    edges.sort((a, b) => a[2] - b[2]);

    const uf = new UnionFind(n);
    const mst = [];
    let totalWeight = 0;

    for (const [u, v, weight] of edges) {
        if (uf.union(u, v)) {
            mst.push([u, v, weight]);
            totalWeight += weight;
        }
    }

    return { mst, totalWeight };
}

public class TarjanSCC {
    private int time = 0;
    private List<List<Integer>> sccs = new ArrayList<>();

    public List<List<Integer>> findSCCs(Map<Integer, List<Integer>> graph, int n) {
        int[] disc = new int[n];
        int[] low = new int[n];
        boolean[] onStack = new boolean[n];
        Stack<Integer> stack = new Stack<>();
        Arrays.fill(disc, -1);

        for (int i = 0; i < n; i++) {
            if (disc[i] == -1) {
                dfs(i, graph, disc, low, onStack, stack);
            }
        }

        return sccs;
    }

    private void dfs(int u, Map<Integer, List<Integer>> graph, int[] disc, 
                     int[] low, boolean[] onStack, Stack<Integer> stack) {
        disc[u] = low[u] = time++;
        stack.push(u);
        onStack[u] = true;

        for (int v : graph.getOrDefault(u, new ArrayList<>())) {
            if (disc[v] == -1) {
                dfs(v, graph, disc, low, onStack, stack);
                low[u] = Math.min(low[u], low[v]);
            } else if (onStack[v]) {
                low[u] = Math.min(low[u], disc[v]);
            }
        }

        if (low[u] == disc[u]) {
            List<Integer> scc = new ArrayList<>();
            int v;
            do {
                v = stack.pop();
                onStack[v] = false;
                scc.add(v);
            } while (v != u);
            sccs.add(scc);
        }
    }
}

def matrix_chain_multiplication(dimensions):
    """
    Find minimum number of scalar multiplications for matrix chain
    dimensions: array where matrix i has dimensions[i-1] x dimensions[i]
    """
    n = len(dimensions) - 1
    dp = [[0] * n for _ in range(n)]
    split = [[0] * n for _ in range(n)]

    # l is chain length
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            dp[i][j] = float('inf')

            for k in range(i, j):
                cost = (dp[i][k] + dp[k + 1][j] + 
                       dimensions[i] * dimensions[k + 1] * dimensions[j + 1])
                if cost < dp[i][j]:
                    dp[i][j] = cost
                    split[i][j] = k

    def get_parenthesization(i, j):
        if i == j:
            return f"M{i}"
        k = split[i][j]
        return f"({get_parenthesization(i, k)} x {get_parenthesization(k + 1, j)})"

    return dp[0][n - 1], get_parenthesization(0, n - 1)

#include <vector>
#include <algorithm>
using namespace std;

class SegmentTree {
private:
    vector<int> tree;
    int n;

    void build(vector<int>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = (start + end) / 2;
            build(arr, 2 * node, start, mid);
            build(arr, 2 * node + 1, mid + 1, end);
            tree[node] = tree[2 * node] + tree[2 * node + 1];
        }
    }

    void updateHelper(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
        } else {
            int mid = (start + end) / 2;
            if (idx <= mid) {
                updateHelper(2 * node, start, mid, idx, val);
            } else {
                updateHelper(2 * node + 1, mid + 1, end, idx, val);
            }
            tree[node] = tree[2 * node] + tree[2 * node + 1];
        }
    }

    int queryHelper(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return tree[node];

        int mid = (start + end) / 2;
        int leftSum = queryHelper(2 * node, start, mid, l, r);
        int rightSum = queryHelper(2 * node + 1, mid + 1, end, l, r);
        return leftSum + rightSum;
    }

public:
    SegmentTree(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 1, 0, n - 1);
    }

    void update(int idx, int val) {
        updateHelper(1, 0, n - 1, idx, val);
    }

    int query(int l, int r) {
        return queryHelper(1, 0, n - 1, l, r);
    }
};

function manachersPalindrome(s) {
    // Preprocess string: "abc" -> "^#a#b#c#$"
    let t = '^#' + s.split('').join('#') + '#$';
    let n = t.length;
    let p = new Array(n).fill(0);
    let center = 0, right = 0;

    for (let i = 1; i < n - 1; i++) {
        let mirror = 2 * center - i;

        if (i < right) {
            p[i] = Math.min(right - i, p[mirror]);
        }

        // Expand around center i
        while (t[i + p[i] + 1] === t[i - p[i] - 1]) {
            p[i]++;
        }

        // Update center and right boundary
        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
        }
    }

    // Find longest palindrome
    let maxLen = 0, centerIndex = 0;
    for (let i = 1; i < n - 1; i++) {
        if (p[i] > maxLen) {
            maxLen = p[i];
            centerIndex = i;
        }
    }

    let start = (centerIndex - maxLen) / 2;
    return s.substr(start, maxLen);
}

def aho_corasick(text, patterns):
    """
    Aho-Corasick algorithm for multiple pattern matching
    """
    from collections import deque, defaultdict

    # Build trie
    trie = {}
    outputs = defaultdict(list)
    node_id = 0

    for pattern in patterns:
        node = trie
        for char in pattern:
            if char not in node:
                node_id += 1
                node[char] = {'id': node_id}
            node = node[char]
        outputs[node.get('id', 0)].append(pattern)

    # Build failure links (BFS)
    fail = {}
    queue = deque()

    for char in trie:
        if isinstance(trie[char], dict):
            fail[trie[char]['id']] = 0
            queue.append(trie[char])

    while queue:
        node = queue.popleft()
        for char in node:
            if char == 'id':
                continue
            child = node[char]
            queue.append(child)

            # Find failure link
            f = fail.get(node.get('id', 0), 0)
            while f != 0 and char not in trie:
                f = fail[f]
            fail[child['id']] = trie.get(char, {}).get('id', 0) if f == 0 else f

    # Search
    matches = []
    node = trie
    for i, char in enumerate(text):
        while node != trie and char not in node:
            node = trie  # Simplified for demo

        if char in node:
            node = node[char]
            if node.get('id') in outputs:
                for pattern in outputs[node['id']]:
                    matches.append((i - len(pattern) + 1, pattern))

    return matches

public class FenwickTree {
    private int[] tree;
    private int n;

    public FenwickTree(int n) {
        this.n = n;
        this.tree = new int[n + 1];
    }

    // Update value at index (1-indexed)
    public void update(int index, int delta) {
        while (index <= n) {
            tree[index] += delta;
            index += index & (-index);
        }
    }

    // Get prefix sum up to index (1-indexed)
    public int query(int index) {
        int sum = 0;
        while (index > 0) {
            sum += tree[index];
            index -= index & (-index);
        }
        return sum;
    }

    // Range sum query [left, right] (1-indexed)
    public int rangeQuery(int left, int right) {
        return query(right) - query(left - 1);
    }

    // Build tree from array
    public static FenwickTree build(int[] arr) {
        FenwickTree ft = new FenwickTree(arr.length);
        for (int i = 0; i < arr.length; i++) {
            ft.update(i + 1, arr[i]);
        }
        return ft;
    }
}

