using namespace std;

class FastFourierTransform {
public:
    struct Complex {
        double real, imag;
        Complex(double r = 0, double i = 0) : real(r), imag(i) {}
        Complex operator+(const Complex& other) const {
            return Complex(real + other.real, imag + other.imag);
        }
        Complex operator-(const Complex& other) const {
            return Complex(real - other.real, imag - other.imag);
        }
        Complex operator*(const Complex& other) const {
            return Complex(real * other.real - imag * other.imag,
                         real * other.imag + imag * other.real);
        }
    };

    void fft(vector<Complex>& a, bool invert) {
        int n = a.size();
        if (n == 1) return;

        vector<Complex> a0(n / 2), a1(n / 2);
        for (int i = 0; i < n / 2; i++) {
            a0[i] = a[2 * i];
            a1[i] = a[2 * i + 1];
        }

        fft(a0, invert);
        fft(a1, invert);

        double angle = 2 * M_PI / n * (invert ? -1 : 1);
        Complex w(1), wn(cos(angle), sin(angle));

        for (int i = 0; i < n / 2; i++) {
            a[i] = a0[i] + w * a1[i];
            a[i + n / 2] = a0[i] - w * a1[i];
            if (invert) {
                a[i].real /= 2;
                a[i].imag /= 2;
                a[i + n / 2].real /= 2;
                a[i + n / 2].imag /= 2;
            }
            w = w * wn;
        }
    }

    vector<int> multiply(vector<int>& a, vector<int>& b) {
        vector<Complex> fa(a.begin(), a.end()), fb(b.begin(), b.end());
        int n = 1;
        while (n < a.size() + b.size()) n <<= 1;
        fa.resize(n);
        fb.resize(n);

        fft(fa, false);
        fft(fb, false);

        for (int i = 0; i < n; i++) {
            fa[i] = fa[i] * fb[i];
        }

        fft(fa, true);

        vector<int> result(n);
        for (int i = 0; i < n; i++) {
            result[i] = round(fa[i].real);
        }
        return result;
    }
};

function euclideanGCD(a, b) {
    // Iterative Euclidean algorithm
    while (b !== 0) {
        [a, b] = [b, a % b];
    }
    return a;
}

function extendedGCD(a, b) {
    // Returns [gcd, x, y] where gcd = a*x + b*y
    if (b === 0) {
        return [a, 1, 0];
    }

    const [gcd, x1, y1] = extendedGCD(b, a % b);
    const x = y1;
    const y = x1 - Math.floor(a / b) * y1;

    return [gcd, x, y];
}

function modularInverse(a, m) {
    const [gcd, x, _] = extendedGCD(a, m);
    if (gcd !== 1) {
        return null; // Inverse doesn't exist
    }
    return ((x % m) + m) % m;
}

def sieve_of_eratosthenes(n):
    """Generate all primes up to n using Sieve of Eratosthenes"""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(n + 1) if is_prime[i]]

def segmented_sieve(left, right):
    """Find primes in range [left, right] using segmented sieve"""
    limit = int(right**0.5) + 1
    base_primes = sieve_of_eratosthenes(limit)

    size = right - left + 1
    is_prime = [True] * size

    for prime in base_primes:
        start = max(prime * prime, ((left + prime - 1) // prime) * prime)
        for j in range(start, right + 1, prime):
            is_prime[j - left] = False

    return [left + i for i in range(size) if is_prime[i] and left + i > 1]

public class QuickSelect {
    // Find kth smallest element in unsorted array
    public int quickSelect(int[] arr, int k) {
        return quickSelectHelper(arr, 0, arr.length - 1, k - 1);
    }

    private int quickSelectHelper(int[] arr, int left, int right, int k) {
        if (left == right) return arr[left];

        // Random pivot for better average case
        int pivotIndex = left + (int)(Math.random() * (right - left + 1));
        pivotIndex = partition(arr, left, right, pivotIndex);

        if (k == pivotIndex) {
            return arr[k];
        } else if (k < pivotIndex) {
            return quickSelectHelper(arr, left, pivotIndex - 1, k);
        } else {
            return quickSelectHelper(arr, pivotIndex + 1, right, k);
        }
    }

    private int partition(int[] arr, int left, int right, int pivotIndex) {
        int pivotValue = arr[pivotIndex];
        swap(arr, pivotIndex, right);
        int storeIndex = left;

        for (int i = left; i < right; i++) {
            if (arr[i] < pivotValue) {
                swap(arr, storeIndex, i);
                storeIndex++;
            }
        }

        swap(arr, right, storeIndex);
        return storeIndex;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

function longestPalindromicSubsequence(s) {
    const n = s.length;
    const dp = Array(n).fill(null).map(() => Array(n).fill(0));

    // Every single character is a palindrome of length 1
    for (let i = 0; i < n; i++) {
        dp[i][i] = 1;
    }

    // Build table bottom-up
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;

            if (s[i] === s[j]) {
                dp[i][j] = 2 + (len === 2 ? 0 : dp[i + 1][j - 1]);
            } else {
                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }

    return dp[0][n - 1];
}

