using namespace std;

class WordBreak {
public:
    bool wordBreak(string s, unordered_set<string>& wordDict) {
        int n = s.length();
        vector<bool> dp(n + 1, false);
        dp[0] = true;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                if (dp[j] && wordDict.count(s.substr(j, i - j))) {
                    dp[i] = true;
                    break;
                }
            }
        }

        return dp[n];
    }

    vector<string> wordBreakAll(string s, unordered_set<string>& wordDict) {
        unordered_map<int, vector<string>> memo;
        return helper(s, 0, wordDict, memo);
    }

private:
    vector<string> helper(const string& s, int start, 
                         unordered_set<string>& wordDict,
                         unordered_map<int, vector<string>>& memo) {
        if (memo.count(start)) return memo[start];

        vector<string> result;
        if (start == s.length()) {
            result.push_back("");
            return result;
        }

        for (int end = start + 1; end <= s.length(); end++) {
            string word = s.substr(start, end - start);
            if (wordDict.count(word)) {
                vector<string> rest = helper(s, end, wordDict, memo);
                for (const string& r : rest) {
                    result.push_back(word + (r.empty() ? "" : " ") + r);
                }
            }
        }

        memo[start] = result;
        return result;
    }
};

class Singleton:
    """Thread-safe Singleton implementation using metaclass"""
    _instances = {}
    _lock = threading.Lock()

    def __new__(cls):
        if cls not in cls._instances:
            with cls._lock:
                if cls not in cls._instances:
                    cls._instances[cls] = super().__new__(cls)
        return cls._instances[cls]

class DatabaseConnection(Singleton):
    def __init__(self):
        if not hasattr(self, 'initialized'):
            self.connection = None
            self.initialized = True

    def connect(self, connection_string):
        if self.connection is None:
            self.connection = connection_string
            print(f"Connected to database: {connection_string}")
        return self.connection

# Alternative using decorator
def singleton(cls):
    instances = {}
    lock = threading.Lock()

    def get_instance(*args, **kwargs):
        if cls not in instances:
            with lock:
                if cls not in instances:
                    instances[cls] = cls(*args, **kwargs)
        return instances[cls]

    return get_instance

@singleton
