from abc import ABC, abstractmethod
from copy import deepcopy
import copy

class Prototype(ABC):
    """Abstract prototype class"""

    @abstractmethod
    def clone(self):
        pass

class Shape(Prototype):
    def __init__(self, x, y, color):
        self.x = x
        self.y = y
        self.color = color

    def clone(self):
        return copy.deepcopy(self)

class Circle(Shape):
    def __init__(self, x, y, color, radius):
        super().__init__(x, y, color)
        self.radius = radius

    def __str__(self):
        return f"Circle at ({self.x}, {self.y}), color: {self.color}, radius: {self.radius}"

class Rectangle(Shape):
    def __init__(self, x, y, color, width, height):
        super().__init__(x, y, color)
        self.width = width
        self.height = height

    def __str__(self):
        return f"Rectangle at ({self.x}, {self.y}), color: {self.color}, size: {self.width}x{self.height}"

class ShapeRegistry:
    """Registry for managing prototypes"""

    def __init__(self):
        self._prototypes = {}

    def register(self, key, prototype):
        self._prototypes[key] = prototype

    def unregister(self, key):
        del self._prototypes[key]

    def clone(self, key):
        prototype = self._prototypes.get(key)
        if prototype:
            return prototype.clone()
        return None

# Usage
registry = ShapeRegistry()

# Register prototypes
registry.register('blue_circle', Circle(0, 0, 'blue', 10))
registry.register('red_rectangle', Rectangle(0, 0, 'red', 20, 30))

# Clone and modify
circle1 = registry.clone('blue_circle')
circle1.x = 10
circle1.y = 20

circle2 = registry.clone('blue_circle')
circle2.radius = 15

// Adapter Pattern - Making incompatible interfaces work together

// Legacy payment system
class LegacyPaymentProcessor {
  processPayment(amount: number, accountNumber: string): void {
    console.log(`Processing $${amount} from account ${accountNumber}`);
  }
}

// Modern payment interface
interface PaymentGateway {
  pay(amount: number, creditCard: CreditCard): boolean;
}

interface CreditCard {
  number: string;
  cvv: string;
  expiry: string;
}

// Adapter
class PaymentAdapter implements PaymentGateway {
  private legacyProcessor: LegacyPaymentProcessor;

  constructor(legacyProcessor: LegacyPaymentProcessor) {
    this.legacyProcessor = legacyProcessor;
  }

  pay(amount: number, creditCard: CreditCard): boolean {
    try {
      // Convert modern interface to legacy format
      const accountNumber = this.convertCardToAccount(creditCard);
      this.legacyProcessor.processPayment(amount, accountNumber);
      return true;
    } catch (error) {
      console.error('Payment failed:', error);
      return false;
    }
  }

  private convertCardToAccount(card: CreditCard): string {
    // Simplified conversion logic
    return `ACC-${card.number.slice(-4)}`;
  }
}

// Client code
class PaymentService {
  private gateway: PaymentGateway;

  constructor(gateway: PaymentGateway) {
    this.gateway = gateway;
  }

  processOrder(amount: number, card: CreditCard): boolean {
    return this.gateway.pay(amount, card);
  }
}

// Usage
const legacy = new LegacyPaymentProcessor();
const adapter = new PaymentAdapter(legacy);
const service = new PaymentService(adapter);

