from abc import ABC, abstractmethod

# Component interface
class Component(ABC):
    @abstractmethod
    def operation(self) -> str:
        pass

# Concrete component
class ConcreteComponent(Component):
    def operation(self) -> str:
        return "ConcreteComponent"

# Base decorator
class Decorator(Component):
    def __init__(self, component: Component):
        self._component = component

    def operation(self) -> str:
        return self._component.operation()

# Concrete decorators
class LoggingDecorator(Decorator):
    def operation(self) -> str:
        result = self._component.operation()
        print(f"Logging: {result}")
        return result

class TimingDecorator(Decorator):
    def operation(self) -> str:
        import time
        start = time.time()
        result = self._component.operation()
        end = time.time()
        print(f"Execution time: {end - start:.4f}s")
        return result

class CachingDecorator(Decorator):
    def __init__(self, component: Component):
        super().__init__(component)
        self._cache = {}

    def operation(self) -> str:
        cache_key = 'operation'
        if cache_key not in self._cache:
            self._cache[cache_key] = self._component.operation()
            print("Cache miss - computing result")
        else:
            print("Cache hit - returning cached result")
        return self._cache[cache_key]

class ErrorHandlingDecorator(Decorator):
    def operation(self) -> str:
        try:
            return self._component.operation()
        except Exception as e:
            print(f"Error caught: {e}")
            return "Error occurred"

# Usage - decorators can be stacked
component = ConcreteComponent()
