public class Facade {
    // Simplified interface to complex subsystem

    // Subsystem classes
    private class CPU {
        public void freeze() {
            System.out.println("CPU: Freezing...");
        }

        public void jump(long position) {
            System.out.println("CPU: Jumping to " + position);
        }

        public void execute() {
            System.out.println("CPU: Executing...");
        }
    }

    private class Memory {
        public void load(long position, byte[] data) {
            System.out.println("Memory: Loading data at " + position);
        }
    }

    private class HardDrive {
        public byte[] read(long lba, int size) {
            System.out.println("HardDrive: Reading " + size + " bytes from " + lba);
            return new byte[size];
        }
    }

    // Facade
    public static class ComputerFacade {
        private final CPU cpu;
        private final Memory memory;
        private final HardDrive hardDrive;

        private static final long BOOT_ADDRESS = 0x00;
        private static final long BOOT_SECTOR = 0x00;
        private static final int SECTOR_SIZE = 512;

        public ComputerFacade() {
            Facade facade = new Facade();
            this.cpu = facade.new CPU();
            this.memory = facade.new Memory();
            this.hardDrive = facade.new HardDrive();
        }

        public void start() {
            System.out.println("Starting computer...");
            cpu.freeze();
            memory.load(BOOT_ADDRESS, hardDrive.read(BOOT_SECTOR, SECTOR_SIZE));
            cpu.jump(BOOT_ADDRESS);
            cpu.execute();
            System.out.println("Computer started!");
        }
    }

    public static void main(String[] args) {
        ComputerFacade computer = new ComputerFacade();
        computer.start();
    }
}

interface Subject {
  request(): void;
}

class RealSubject implements Subject {
  request(): void {
    console.log('RealSubject: Handling request');
  }
}

class Proxy implements Subject {
  private realSubject: RealSubject | null = null;

  request(): void {
    if (this.checkAccess()) {
      this.realSubject = this.realSubject || new RealSubject();
      this.realSubject.request();
      this.logAccess();
    }
  }

  private checkAccess(): boolean {
    console.log('Proxy: Checking access before forwarding request');
    return true;
  }

  private logAccess(): void {
    console.log('Proxy: Logging access time');
  }
}

// Virtual Proxy - lazy initialization
class ImageProxy {
  private realImage: RealImage | null = null;
  private filename: string;

  constructor(filename: string) {
    this.filename = filename;
  }

  display(): void {
    if (!this.realImage) {
      this.realImage = new RealImage(this.filename);
    }
    this.realImage.display();
  }
}

class RealImage {
  private filename: string;

  constructor(filename: string) {
    this.filename = filename;
    this.loadFromDisk();
  }

  private loadFromDisk(): void {
    console.log(`Loading image: ${this.filename}`);
  }

  display(): void {
    console.log(`Displaying image: ${this.filename}`);
  }
}

// Caching Proxy
class CachingProxy implements Subject {
  private realSubject: RealSubject;
  private cache: Map<string, any> = new Map();

  constructor() {
    this.realSubject = new RealSubject();
  }

  request(): void {
    const cacheKey = 'request';

    if (this.cache.has(cacheKey)) {
      console.log('CachingProxy: Returning cached result');
      return this.cache.get(cacheKey);
    }

    console.log('CachingProxy: Cache miss, forwarding to real subject');
    this.realSubject.request();
    this.cache.set(cacheKey, 'result');
  }
}

from abc import ABC, abstractmethod
from typing import List

# Observer pattern for event-driven systems

class Observer(ABC):
    @abstractmethod
    def update(self, subject) -> None:
        pass

class Subject(ABC):
    def __init__(self):
        self._observers: List[Observer] = []

    def attach(self, observer: Observer) -> None:
        if observer not in self._observers:
            self._observers.append(observer)

    def detach(self, observer: Observer) -> None:
        if observer in self._observers:
            self._observers.remove(observer)

    def notify(self) -> None:
        for observer in self._observers:
            observer.update(self)

class StockMarket(Subject):
    def __init__(self):
        super().__init__()
        self._prices = {}

    def set_price(self, symbol: str, price: float) -> None:
        old_price = self._prices.get(symbol)
        self._prices[symbol] = price

        if old_price != price:
            print(f"Price changed: {symbol} ${old_price} -> ${price}")
            self.notify()

    def get_price(self, symbol: str) -> float:
        return self._prices.get(symbol, 0.0)

    def get_all_prices(self):
        return self._prices.copy()

class Investor(Observer):
    def __init__(self, name: str):
        self.name = name
        self.portfolio = {}

    def update(self, subject: StockMarket) -> None:
        prices = subject.get_all_prices()
        print(f"{self.name} notified of price changes: {prices}")
        self.rebalance_portfolio(prices)

    def rebalance_portfolio(self, prices: dict) -> None:
        # Simple rebalancing logic
        for symbol, price in prices.items():
            if price < 100:
                print(f"{self.name}: Buying {symbol}")
            elif price > 200:
                print(f"{self.name}: Selling {symbol}")

class TradingBot(Observer):
    def __init__(self, strategy: str):
        self.strategy = strategy

    def update(self, subject: StockMarket) -> None:
        prices = subject.get_all_prices()
        print(f"TradingBot ({self.strategy}) analyzing: {prices}")
        self.execute_strategy(prices)

    def execute_strategy(self, prices: dict) -> None:
        for symbol, price in prices.items():
            if self.strategy == 'momentum':
                print(f"TradingBot: Momentum trade on {symbol}")

# Usage
market = StockMarket()

investor1 = Investor("Alice")
investor2 = Investor("Bob")
bot = TradingBot("momentum")

market.attach(investor1)
market.attach(investor2)
market.attach(bot)

market.set_price("AAPL", 150.00)
market.set_price("GOOGL", 2800.00)

market.detach(investor2)
market.set_price("AAPL", 155.00)

// Strategy pattern - encapsulating algorithms

interface PaymentStrategy {
  pay(amount: number): boolean;
}

class CreditCardPayment implements PaymentStrategy {
  private cardNumber: string;
  private cvv: string;

  constructor(cardNumber: string, cvv: string) {
    this.cardNumber = cardNumber;
    this.cvv = cvv;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using Credit Card ****${this.cardNumber.slice(-4)}`);
    return true;
  }
}

class PayPalPayment implements PaymentStrategy {
  private email: string;

  constructor(email: string) {
    this.email = email;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using PayPal account ${this.email}`);
    return true;
  }
}

class CryptoPayment implements PaymentStrategy {
  private walletAddress: string;
  private currency: string;

  constructor(walletAddress: string, currency: string = 'BTC') {
    this.walletAddress = walletAddress;
    this.currency = currency;
  }

  pay(amount: number): boolean {
    console.log(`Paid $${amount} using ${this.currency} to ${this.walletAddress}`);
    return true;
  }
}

class ShoppingCart {
  private items: Array<{ name: string; price: number }> = [];
  private paymentStrategy?: PaymentStrategy;

  addItem(name: string, price: number): void {
    this.items.push({ name, price });
  }

  setPaymentStrategy(strategy: PaymentStrategy): void {
    this.paymentStrategy = strategy;
  }

  checkout(): boolean {
    if (!this.paymentStrategy) {
      console.error('No payment strategy set');
      return false;
    }

    const total = this.items.reduce((sum, item) => sum + item.price, 0);
    return this.paymentStrategy.pay(total);
  }

  getTotal(): number {
    return this.items.reduce((sum, item) => sum + item.price, 0);
  }
}

// Usage
const cart = new ShoppingCart();
cart.addItem('Laptop', 999.99);
cart.addItem('Mouse', 29.99);

// Pay with credit card
cart.setPaymentStrategy(new CreditCardPayment('1234567890123456', '123'));
cart.checkout();

// Pay with PayPal
cart.setPaymentStrategy(new PayPalPayment('user@example.com'));
cart.checkout();

// Pay with crypto
cart.setPaymentStrategy(new CryptoPayment('1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa', 'BTC'));
cart.checkout();

public interface Command {
    void execute();
    void undo();
}

public class Light {
    private boolean isOn = false;

    public void turnOn() {
        isOn = true;
        System.out.println("Light is ON");
    }

    public void turnOff() {
        isOn = false;
        System.out.println("Light is OFF");
    }
}

public class LightOnCommand implements Command {
    private Light light;

    public LightOnCommand(Light light) {
        this.light = light;
    }

    @Override
    public void execute() {
        light.turnOn();
    }

    @Override
    public void undo() {
        light.turnOff();
    }
}

public class LightOffCommand implements Command {
    private Light light;

    public LightOffCommand(Light light) {
        this.light = light;
    }

    @Override
    public void execute() {
        light.turnOff();
    }

    @Override
    public void undo() {
        light.turnOn();
    }
}

public class RemoteControl {
    private Command[] onCommands;
    private Command[] offCommands;
    private Command lastCommand;

    public RemoteControl(int slots) {
        onCommands = new Command[slots];
        offCommands = new Command[slots];

        Command noCommand = new NoCommand();
        for (int i = 0; i < slots; i++) {
            onCommands[i] = noCommand;
            offCommands[i] = noCommand;
        }
        lastCommand = noCommand;
    }

    public void setCommand(int slot, Command onCommand, Command offCommand) {
        onCommands[slot] = onCommand;
        offCommands[slot] = offCommand;
    }

    public void onButtonPressed(int slot) {
        onCommands[slot].execute();
        lastCommand = onCommands[slot];
    }

    public void offButtonPressed(int slot) {
        offCommands[slot].execute();
        lastCommand = offCommands[slot];
    }

    public void undoButtonPressed() {
        lastCommand.undo();
    }
}

public class NoCommand implements Command {
    @Override
    public void execute() {}

    @Override
    public void undo() {}
}

// Macro command for multiple commands
public class MacroCommand implements Command {
    private Command[] commands;

    public MacroCommand(Command[] commands) {
        this.commands = commands;
    }

    @Override
    public void execute() {
        for (Command command : commands) {
            command.execute();
        }
    }

    @Override
    public void undo() {
        for (int i = commands.length - 1; i >= 0; i--) {
            commands[i].undo();
        }
    }
}

from abc import ABC, abstractmethod
from enum import Enum

class State(ABC):
    @abstractmethod
    def insert_coin(self, machine):
        pass

    @abstractmethod
    def eject_coin(self, machine):
        pass

    @abstractmethod
    def dispense(self, machine):
        pass

class NoCoinState(State):
    def insert_coin(self, machine):
        print("Coin inserted")
        machine.set_state(machine.has_coin_state)

    def eject_coin(self, machine):
        print("No coin to eject")

    def dispense(self, machine):
        print("Insert coin first")

class HasCoinState(State):
    def insert_coin(self, machine):
        print("Coin already inserted")

    def eject_coin(self, machine):
        print("Coin ejected")
        machine.set_state(machine.no_coin_state)

    def dispense(self, machine):
        print("Dispensing product...")
        machine.set_state(machine.dispensing_state)
        machine.dispense()

class DispensingState(State):
    def insert_coin(self, machine):
        print("Please wait, dispensing...")

    def eject_coin(self, machine):
        print("Cannot eject, dispensing...")

    def dispense(self, machine):
        if machine.count > 0:
            machine.count -= 1
            print(f"Product dispensed. Remaining: {machine.count}")
            if machine.count > 0:
                machine.set_state(machine.no_coin_state)
            else:
                print("Machine is out of stock")
                machine.set_state(machine.out_of_stock_state)
        else:
            machine.set_state(machine.out_of_stock_state)

class OutOfStockState(State):
    def insert_coin(self, machine):
        print("Out of stock, coin returned")

    def eject_coin(self, machine):
        print("No coin inserted")

    def dispense(self, machine):
        print("Out of stock")

class VendingMachine:
    def __init__(self, count):
        self.count = count

        # Initialize states
        self.no_coin_state = NoCoinState()
        self.has_coin_state = HasCoinState()
        self.dispensing_state = DispensingState()
        self.out_of_stock_state = OutOfStockState()

        # Set initial state
        if count > 0:
            self.state = self.no_coin_state
        else:
            self.state = self.out_of_stock_state

    def set_state(self, state):
        self.state = state

    def insert_coin(self):
        self.state.insert_coin(self)

    def eject_coin(self):
        self.state.eject_coin(self)

    def dispense(self):
        self.state.dispense(self)

    def refill(self, count):
        self.count += count
        print(f"Refilled. Total count: {self.count}")
        if self.count > 0:
            self.state = self.no_coin_state

# Usage
machine = VendingMachine(2)
machine.insert_coin()
machine.dispense()
machine.insert_coin()
machine.dispense()
machine.insert_coin()  # Out of stock

