class APIGateway {
  private userService: UserService;
  private orderService: OrderService;
  private paymentService: PaymentService;
  private inventoryService: InventoryService;
  private cache: Map<string, any>;

  constructor() {
    this.userService = new UserService();
    this.orderService = new OrderService();
    this.paymentService = new PaymentService();
    this.inventoryService = new InventoryService();
    this.cache = new Map();
  }

  async getUserProfile(userId: string): Promise<ServiceResponse> {
    try {
      // Aggregate data from multiple services
      const [userResponse, ordersResponse] = await Promise.all([
        this.userService.getUser(userId),
        this.userService.getUserOrders(userId)
      ]);

      if (userResponse.status !== 200) {
        return userResponse;
      }

      return {
        data: {
          user: userResponse.data,
          orders: ordersResponse.data || [],
          totalOrders: ordersResponse.data?.length || 0
        },
        status: 200
      };
    } catch (error) {
      return {
        error: 'Failed to fetch user profile',
        status: 500
      };
    }
  }

  async createOrder(userId: string, items: any[]): Promise<ServiceResponse> {
    try {
      // Check stock for all items
      const stockChecks = await Promise.all(
        items.map(item => this.inventoryService.checkStock(item.productId))
      );

      const outOfStock = stockChecks.filter(check => !check.data?.inStock);
      if (outOfStock.length > 0) {
        return {
          error: 'Some items are out of stock',
          status: 400
        };
      }

      // Create order
      const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
      const orderResponse = await this.orderService.getOrder('new');

      // Process payment
      const paymentResponse = await this.paymentService.processPayment(
        orderResponse.data?.id,
        total
      );

      if (paymentResponse.status !== 200) {
        return {
          error: 'Payment failed',
          status: 400
        };
      }

      return {
        data: {
          order: orderResponse.data,
          payment: paymentResponse.data
        },
        status: 201
      };
    } catch (error) {
      return {
        error: 'Failed to create order',
        status: 500
      };
    }
  }

  // Rate limiting
  private rateLimitMap = new Map<string, number[]>();

  private checkRateLimit(clientId: string, maxRequests: number = 100, windowMs: number = 60000): boolean {
    const now = Date.now();
    const requests = this.rateLimitMap.get(clientId) || [];

    // Filter out old requests
    const recentRequests = requests.filter(time => now - time < windowMs);

    if (recentRequests.length >= maxRequests) {
      return false;
    }

    recentRequests.push(now);
    this.rateLimitMap.set(clientId, recentRequests);
    return true;
  }

  // Circuit breaker
  private async callWithCircuitBreaker<T>(
    serviceName: string,
    fn: () => Promise<T>
  ): Promise<T> {
    // Simplified circuit breaker logic
    try {
      return await fn();
    } catch (error) {
      console.error(`Service ${serviceName} failed:`, error);
      throw error;
    }
  }
}

import time
import enum
from typing import Callable, Any

class CircuitState(enum.Enum):
    CLOSED = "closed"  # Normal operation
    OPEN = "open"      # Failures detected, blocking calls
    HALF_OPEN = "half_open"  # Testing if service recovered

class CircuitBreaker:
    """
    Circuit Breaker pattern to prevent cascading failures
    """

    def __init__(
        self,
        failure_threshold: int = 5,
        timeout: int = 60,
        recovery_timeout: int = 30
    ):
        self.failure_threshold = failure_threshold
        self.timeout = timeout
        self.recovery_timeout = recovery_timeout

        self.failure_count = 0
        self.last_failure_time = None
        self.state = CircuitState.CLOSED

    def call(self, func: Callable, *args, **kwargs) -> Any:
        if self.state == CircuitState.OPEN:
            if self._should_attempt_reset():
                self.state = CircuitState.HALF_OPEN
                print("Circuit breaker: HALF_OPEN - attempting recovery")
            else:
                raise Exception("Circuit breaker is OPEN - rejecting call")

        try:
            result = func(*args, **kwargs)
            self._on_success()
            return result
        except Exception as e:
            self._on_failure()
            raise e

    def _should_attempt_reset(self) -> bool:
        return (
            self.last_failure_time is not None and
            time.time() - self.last_failure_time >= self.recovery_timeout
        )

    def _on_success(self):
        self.failure_count = 0
        if self.state == CircuitState.HALF_OPEN:
            self.state = CircuitState.CLOSED
            print("Circuit breaker: CLOSED - service recovered")

    def _on_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.time()

        if self.failure_count >= self.failure_threshold:
            self.state = CircuitState.OPEN
            print(f"Circuit breaker: OPEN - {self.failure_count} failures detected")

    def reset(self):
        """Manually reset the circuit breaker"""
        self.failure_count = 0
        self.state = CircuitState.CLOSED
        print("Circuit breaker: manually RESET")

# Example service with circuit breaker
class ExternalService:
    def __init__(self):
        self.circuit_breaker = CircuitBreaker(
            failure_threshold=3,
            timeout=60,
            recovery_timeout=10
        )
        self.call_count = 0

    def _make_request(self, data):
        self.call_count += 1
        # Simulate failures
        if self.call_count <= 5:
            raise Exception("Service temporarily unavailable")
        return f"Success: {data}"

    def call_external_api(self, data):
        try:
            return self.circuit_breaker.call(self._make_request, data)
        except Exception as e:
            print(f"Error: {e}")
            return None

# Usage
service = ExternalService()

for i in range(10):
    print(f"\nAttempt {i + 1}:")
    result = service.call_external_api(f"request_{i}")
    if result:
        print(f"Result: {result}")
    time.sleep(1)

// Saga Pattern for distributed transactions

interface SagaStep {
  execute(): Promise<any>;
  compensate(): Promise<void>;
}

class SagaOrchestrator {
  private steps: SagaStep[] = [];
  private executedSteps: SagaStep[] = [];

  addStep(step: SagaStep): void {
    this.steps.push(step);
  }

  async execute(): Promise<boolean> {
    try {
      for (const step of this.steps) {
        console.log(`Executing step: ${step.constructor.name}`);
        await step.execute();
        this.executedSteps.push(step);
      }
      console.log('Saga completed successfully');
      return true;
    } catch (error) {
      console.error('Saga failed, starting compensation:', error);
      await this.compensate();
      return false;
    }
  }

  private async compensate(): Promise<void> {
    // Compensate in reverse order
    for (let i = this.executedSteps.length - 1; i >= 0; i--) {
      const step = this.executedSteps[i];
      try {
        console.log(`Compensating step: ${step.constructor.name}`);
        await step.compensate();
      } catch (error) {
        console.error(`Compensation failed for ${step.constructor.name}:`, error);
      }
    }
    this.executedSteps = [];
  }
}

