const prisma = new PrismaClient();

class PostService {
  async createPost(data) {
    return await prisma.post.create({
      data: {
        title: data.title,
        content: data.content,
        author: {
          connect: { id: data.authorId },
        },
        tags: {
          connectOrCreate: data.tags.map((tag) => ({
            where: { name: tag },
            create: { name: tag },
          })),
        },
      },
      include: {
        author: true,
        tags: true,
      },
    });
  }

  async getPosts(options = {}) {
    const { page = 1, limit = 10, orderBy = 'createdAt', order = 'desc' } = options;

    const [posts, total] = await Promise.all([
      prisma.post.findMany({
        skip: (page - 1) * limit,
        take: limit,
        orderBy: { [orderBy]: order },
        include: {
          author: {
            select: {
              id: true,
              name: true,
              email: true,
            },
          },
          tags: true,
          _count: {
            select: { comments: true },
          },
        },
        where: {
          published: true,
        },
      }),
      prisma.post.count({ where: { published: true } }),
    ]);

    return {
      posts,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    };
  }

  async getPostById(id) {
    return await prisma.post.findUnique({
      where: { id },
      include: {
        author: true,
        tags: true,
        comments: {
          include: {
            author: true,
          },
          orderBy: {
            createdAt: 'desc',
          },
        },
      },
    });
  }

  async updatePost(id, data) {
    return await prisma.post.update({
      where: { id },
      data: {
        title: data.title,
        content: data.content,
        published: data.published,
        tags: {
          set: [],
          connectOrCreate: data.tags?.map((tag) => ({
            where: { name: tag },
            create: { name: tag },
          })),
        },
      },
      include: {
        author: true,
        tags: true,
      },
    });
  }

  async deletePost(id) {
    return await prisma.post.delete({
      where: { id },
    });
  }

  async searchPosts(query) {
    return await prisma.post.findMany({
      where: {
        OR: [
          { title: { contains: query, mode: 'insensitive' } },
          { content: { contains: query, mode: 'insensitive' } },
        ],
        published: true,
      },
      include: {
        author: true,
        tags: true,
      },
    });
  }

  async getPostsByTag(tagName) {
    return await prisma.post.findMany({
      where: {
        tags: {
          some: {
            name: tagName,
          },
        },
        published: true,
      },
      include: {
        author: true,
        tags: true,
      },
    });
  }
}

const WebSocket = require('ws');
const http = require('http');
const express = require('express');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const clients = new Map();
const rooms = new Map();

class WebSocketManager {
  static broadcast(room, message, excludeId = null) {
    const roomClients = rooms.get(room) || new Set();

    roomClients.forEach((clientId) => {
      if (clientId !== excludeId) {
        const client = clients.get(clientId);
        if (client && client.readyState === WebSocket.OPEN) {
          client.send(JSON.stringify(message));
        }
      }
    });
  }

  static joinRoom(clientId, room) {
    if (!rooms.has(room)) {
      rooms.set(room, new Set());
    }
    rooms.get(room).add(clientId);

    this.broadcast(room, {
      type: 'user-joined',
      userId: clientId,
      roomId: room,
    });
  }

  static leaveRoom(clientId, room) {
    const roomClients = rooms.get(room);
    if (roomClients) {
      roomClients.delete(clientId);
      if (roomClients.size === 0) {
        rooms.delete(room);
      } else {
        this.broadcast(room, {
          type: 'user-left',
          userId: clientId,
          roomId: room,
        });
      }
    }
  }
}

wss.on('connection', (ws, req) => {
  const clientId = generateId();
  clients.set(clientId, ws);

  console.log(`Client ${clientId} connected`);

  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);

      switch (message.type) {
        case 'join':
          WebSocketManager.joinRoom(clientId, message.room);
          ws.send(JSON.stringify({
            type: 'joined',
            roomId: message.room,
            clientId,
          }));
          break;

        case 'leave':
          WebSocketManager.leaveRoom(clientId, message.room);
          break;

        case 'message':
          WebSocketManager.broadcast(
            message.room,
            {
              type: 'message',
              content: message.content,
              userId: clientId,
              timestamp: new Date().toISOString(),
            },
            clientId
          );
          break;

        default:
          console.log('Unknown message type:', message.type);
      }
    } catch (error) {
      console.error('Error processing message:', error);
    }
  });

  ws.on('close', () => {
    console.log(`Client ${clientId} disconnected`);

    // Remove from all rooms
    rooms.forEach((roomClients, room) => {
      if (roomClients.has(clientId)) {
        WebSocketManager.leaveRoom(clientId, room);
      }
    });

    clients.delete(clientId);
  });

  ws.on('error', (error) => {
    console.error(`WebSocket error for client ${clientId}:`, error);
  });

  // Send welcome message
  ws.send(JSON.stringify({
    type: 'welcome',
    clientId,
  }));
});

function generateId() {
  return Math.random().toString(36).substring(2, 15);
}

server.listen(3000, () => {
  console.log('WebSocket server running on port 3000');
});

import { io, Socket } from 'socket.io-client';
import { useEffect, useState, useCallback } from 'react';

interface Message {
  id: string;
  content: string;
  userId: string;
  timestamp: string;
}

function useSocket(url: string) {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    const newSocket = io(url, {
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionAttempts: 5,
    });

    newSocket.on('connect', () => {
      console.log('Socket connected');
      setConnected(true);
    });

    newSocket.on('disconnect', () => {
      console.log('Socket disconnected');
      setConnected(false);
    });

    setSocket(newSocket);

    return () => {
      newSocket.close();
    };
  }, [url]);

  return { socket, connected };
}

function ChatRoom({ roomId }: { roomId: string }) {
  const { socket, connected } = useSocket('http://localhost:3000');
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [users, setUsers] = useState<string[]>([]);

  useEffect(() => {
    if (!socket) return;

    socket.emit('join-room', roomId);

    socket.on('message', (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    socket.on('user-joined', ({ userId }: { userId: string }) => {
      setUsers((prev) => [...prev, userId]);
    });

    socket.on('user-left', ({ userId }: { userId: string }) => {
      setUsers((prev) => prev.filter((id) => id !== userId));
    });

    socket.on('room-users', ({ users }: { users: string[] }) => {
      setUsers(users);
    });

    return () => {
      socket.emit('leave-room', roomId);
      socket.off('message');
      socket.off('user-joined');
      socket.off('user-left');
      socket.off('room-users');
    };
  }, [socket, roomId]);

  const sendMessage = useCallback(() => {
    if (!socket || !inputValue.trim()) return;

    socket.emit('send-message', {
      roomId,
      content: inputValue,
    });

    setInputValue('');
  }, [socket, roomId, inputValue]);

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="chat-room">
      <div className="users-panel">
        <h3>Users ({users.length})</h3>
        <ul>
          {users.map((userId) => (
            <li key={userId}>{userId}</li>
          ))}
        </ul>
      </div>

      <div className="messages-panel">
        <div className="messages">
          {messages.map((msg) => (
            <div key={msg.id} className="message">
              <strong>{msg.userId}:</strong> {msg.content}
              <span className="timestamp">{msg.timestamp}</span>
            </div>
          ))}
        </div>

        <div className="input-area">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Type a message..."
            disabled={!connected}
          />
          <button onClick={sendMessage} disabled={!connected}>
            Send
          </button>
        </div>
      </div>
    </div>
  );
}

class ErrorHandler extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends ErrorHandler {
  constructor(message) {
    super(message, 400);
  }
}

class UnauthorizedError extends ErrorHandler {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

class ForbiddenError extends ErrorHandler {
  constructor(message = 'Forbidden') {
    super(message, 403);
  }
}

class NotFoundError extends ErrorHandler {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

const errorHandler = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else {
    let error = { ...err };
    error.message = err.message;

    // Mongoose bad ObjectId
    if (err.name === 'CastError') {
      error = new ValidationError(`Invalid ${err.path}: ${err.value}`);
    }

    // Mongoose duplicate key
    if (err.code === 11000) {
      const field = Object.keys(err.keyValue)[0];
      error = new ValidationError(`Duplicate field value: ${field}`);
    }

    // Mongoose validation error
    if (err.name === 'ValidationError') {
      const errors = Object.values(err.errors).map((e) => e.message);
      error = new ValidationError(`Invalid input data: ${errors.join(', ')}`);
    }

    // JWT errors
    if (err.name === 'JsonWebTokenError') {
      error = new UnauthorizedError('Invalid token');
    }

    if (err.name === 'TokenExpiredError') {
      error = new UnauthorizedError('Token expired');
    }

    sendErrorProd(error, res);
  }
};

const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack,
  });
};

const sendErrorProd = (err, res) => {
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
    });
  } else {
    console.error('ERROR:', err);
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong',
    });
  }
};

module.exports = {
  ErrorHandler,
  ValidationError,
  UnauthorizedError,
  ForbiddenError,
  NotFoundError,
  errorHandler,
};

from fastapi import FastAPI, Depends, Query
from sqlalchemy.orm import Session
from typing import List, Optional
from pydantic import BaseModel
import math

app = FastAPI()

class PaginationParams(BaseModel):
    page: int = 1
    size: int = 10

    @property
    def offset(self) -> int:
        return (self.page - 1) * self.size

class PaginatedResponse(BaseModel):
    items: List[dict]
    total: int
    page: int
    size: int
    pages: int

    @classmethod
    def create(cls, items: List, total: int, page: int, size: int):
        return cls(
            items=items,
            total=total,
            page=page,
            size=size,
            pages=math.ceil(total / size) if size > 0 else 0
        )

class CursorPaginationParams(BaseModel):
    cursor: Optional[str] = None
    limit: int = 10

@app.get("/posts")
async def get_posts(
    page: int = Query(1, ge=1),
    size: int = Query(10, ge=1, le=100),
    db: Session = Depends(get_db)
):
    # Offset-based pagination
    offset = (page - 1) * size

    posts = db.query(Post).offset(offset).limit(size).all()
    total = db.query(Post).count()

    return PaginatedResponse.create(
        items=[post.to_dict() for post in posts],
        total=total,
        page=page,
        size=size
    )

@app.get("/posts/cursor")
async def get_posts_cursor(
    cursor: Optional[str] = None,
    limit: int = Query(10, ge=1, le=100),
    db: Session = Depends(get_db)
):
    # Cursor-based pagination (more efficient for large datasets)
    query = db.query(Post).order_by(Post.created_at.desc())

    if cursor:
        decoded_cursor = decode_cursor(cursor)
        query = query.filter(Post.created_at < decoded_cursor)

    posts = query.limit(limit + 1).all()

    has_next = len(posts) > limit
    items = posts[:limit]

    next_cursor = None
    if has_next:
        next_cursor = encode_cursor(items[-1].created_at)

    return {
        "items": [post.to_dict() for post in items],
        "next_cursor": next_cursor,
        "has_next": has_next
    }

def encode_cursor(timestamp) -> str:
    import base64
    return base64.b64encode(str(timestamp).encode()).decode()

def decode_cursor(cursor: str):
    import base64
    from datetime import datetime
    decoded = base64.b64decode(cursor).decode()
    return datetime.fromisoformat(decoded)

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

const createPostSchema = z.object({
  title: z.string().min(1).max(200),
  content: z.string().min(1),
  published: z.boolean().optional(),
});

// GET /api/posts
export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const page = parseInt(searchParams.get('page') || '1');
  const limit = parseInt(searchParams.get('limit') || '10');
  const skip = (page - 1) * limit;

  try {
    const [posts, total] = await Promise.all([
      prisma.post.findMany({
        skip,
        take: limit,
        include: {
          author: {
            select: { name: true, email: true },
          },
        },
        orderBy: { createdAt: 'desc' },
      }),
      prisma.post.count(),
    ]);

    return NextResponse.json({
      posts,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    });
  } catch (error) {
    return NextResponse.json(
      { error: 'Failed to fetch posts' },
      { status: 500 }
    );
  }
}

// POST /api/posts
export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions);

  if (!session?.user?.email) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  try {
    const body = await request.json();
    const validatedData = createPostSchema.parse(body);

    const user = await prisma.user.findUnique({
      where: { email: session.user.email },
    });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    const post = await prisma.post.create({
      data: {
        ...validatedData,
        authorId: user.id,
      },
      include: {
        author: {
          select: { name: true, email: true },
        },
      },
    });

    return NextResponse.json(post, { status: 201 });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Validation error', details: error.errors },
        { status: 400 }
      );
    }

    return NextResponse.json(
      { error: 'Failed to create post' },
      { status: 500 }
    );
  }
}

import { redis } from '@/lib/redis';
import { NextRequest, NextResponse } from 'next/server';

const CACHE_TTL = 60 * 5; // 5 minutes
const RATE_LIMIT_WINDOW = 60; // 1 minute
const RATE_LIMIT_MAX = 100;

export async function withCache(
  request: NextRequest,
  handler: () => Promise<any>,
  cacheKey: string,
  ttl: number = CACHE_TTL
) {
  try {
    // Try to get from cache
    const cached = await redis.get(cacheKey);

    if (cached) {
      return NextResponse.json(JSON.parse(cached), {
        headers: { 'X-Cache': 'HIT' },
      });
    }

    // Execute handler
    const result = await handler();

    // Store in cache
    await redis.setex(cacheKey, ttl, JSON.stringify(result));

    return NextResponse.json(result, {
      headers: { 'X-Cache': 'MISS' },
    });
  } catch (error) {
    console.error('Cache error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function withRateLimit(
  request: NextRequest,
  handler: () => Promise<NextResponse>
) {
  const ip = request.headers.get('x-forwarded-for') || 'unknown';
  const key = `rate_limit:${ip}`;

  try {
    const requests = await redis.incr(key);

    if (requests === 1) {
      await redis.expire(key, RATE_LIMIT_WINDOW);
    }

    if (requests > RATE_LIMIT_MAX) {
      return NextResponse.json(
        { error: 'Too many requests' },
        { 
          status: 429,
          headers: {
            'X-RateLimit-Limit': RATE_LIMIT_MAX.toString(),
            'X-RateLimit-Remaining': '0',
            'Retry-After': RATE_LIMIT_WINDOW.toString(),
          },
        }
      );
    }

    const response = await handler();

    response.headers.set('X-RateLimit-Limit', RATE_LIMIT_MAX.toString());
    response.headers.set(
      'X-RateLimit-Remaining',
      (RATE_LIMIT_MAX - requests).toString()
    );

    return response;
  } catch (error) {
    console.error('Rate limit error:', error);
    return await handler();
  }
}

