def deprecated(new_version):
    """Decorator to mark endpoints as deprecated"""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            response = f(*args, **kwargs)
            if isinstance(response, tuple):
                data, status = response
            else:
                data, status = response, 200

            return data, status, {
                'X-API-Deprecated': 'true',
                'X-API-Version': new_version,
                'Warning': f'299 - "This endpoint is deprecated. Use {new_version}"'
            }
        return wrapper
    return decorator

