class AuthService {
    async hashPassword(password: string): Promise<string> {
        const salt = await bcrypt.genSalt(12);
        return bcrypt.hash(password, salt);
    }

    async verifyPassword(password: string, hash: string): Promise<boolean> {
        return bcrypt.compare(password, hash);
    }

    generateAccessToken(userId: string): string {
        return jwt.sign(
            { userId, type: 'access' },
            process.env.JWT_SECRET!,
            { expiresIn: '15m' }
        );
    }

    generateRefreshToken(userId: string): string {
        return jwt.sign(
            { userId, type: 'refresh' },
            process.env.JWT_REFRESH_SECRET!,
            { expiresIn: '7d' }
        );
    }

    verifyToken(token: string, type: 'access' | 'refresh'): any {
        const secret = type === 'access' 
            ? process.env.JWT_SECRET! 
            : process.env.JWT_REFRESH_SECRET!;

        try {
            return jwt.verify(token, secret);
        } catch (error) {
            throw new Error('Invalid token');
        }
    }

    generatePasswordResetToken(): string {
        return crypto.randomBytes(32).toString('hex');
    }
}

export default new AuthService();

from functools import wraps
from flask import request, jsonify
import jwt
from datetime import datetime, timedelta

class TokenManager:
    def __init__(self, secret_key, algorithm='HS256'):
        self.secret_key = secret_key
        self.algorithm = algorithm

    def create_token(self, user_id, expires_in=3600):
        """Create JWT token with expiration"""
        payload = {
            'user_id': user_id,
            'exp': datetime.utcnow() + timedelta(seconds=expires_in),
            'iat': datetime.utcnow()
        }
        return jwt.encode(payload, self.secret_key, algorithm=self.algorithm)

    def verify_token(self, token):
        """Verify and decode JWT token"""
        try:
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
            return payload
        except jwt.ExpiredSignatureError:
            raise ValueError('Token has expired')
        except jwt.InvalidTokenError:
            raise ValueError('Invalid token')

def require_auth(f):
    """Decorator to protect endpoints"""
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')

        if not token:
            return jsonify({'error': 'No token provided'}), 401

        try:
            token_manager = TokenManager(app.config['SECRET_KEY'])
            payload = token_manager.verify_token(token)
            request.user_id = payload['user_id']
        except ValueError as e:
            return jsonify({'error': str(e)}), 401

        return f(*args, **kwargs)

    return decorated

# Usage
@app.route('/api/protected')
@require_auth
def protected_route():
    return jsonify({'user_id': request.user_id})

