class PaginationHelper {
    static paginate(query, page = 1, limit = 10) {
        const offset = (page - 1) * limit;

        return {
            query: query.limit(limit).offset(offset),
            getMeta: async (total) => ({
                page,
                limit,
                total,
                totalPages: Math.ceil(total / limit),
                hasNext: page * limit < total,
                hasPrev: page > 1
            })
        };
    }

    static buildResponse(data, meta) {
        return {
            data,
            pagination: meta,
            links: {
                self: `/api/resource?page=${meta.page}&limit=${meta.limit}`,
                first: `/api/resource?page=1&limit=${meta.limit}`,
                last: `/api/resource?page=${meta.totalPages}&limit=${meta.limit}`,
                ...(meta.hasNext && {
                    next: `/api/resource?page=${meta.page + 1}&limit=${meta.limit}`
                }),
                ...(meta.hasPrev && {
                    prev: `/api/resource?page=${meta.page - 1}&limit=${meta.limit}`
                })
            }
        };
    }
}

// Usage in controller
async function getUsers(req, res) {
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    const [total, users] = await Promise.all([
        User.count(),
        PaginationHelper.paginate(User.query(), page, limit).query
    ]);

    const meta = await PaginationHelper.paginate(
        User.query(), page, limit
    ).getMeta(total);

    res.json(PaginationHelper.buildResponse(users, meta));
}

import { createClient } from 'redis';
import { promisify } from 'util';

class DistributedLock {
    constructor(redisClient) {
        this.redis = redisClient;
    }

    async acquire(lockKey, ttl = 10000) {
        const lockValue = Math.random().toString(36);
        const acquired = await this.redis.set(
            `lock:${lockKey}`,
            lockValue,
            'PX', ttl,
            'NX'
        );

        return acquired ? lockValue : null;
    }

    async release(lockKey, lockValue) {
        const script = `
            if redis.call("get", KEYS[1]) == ARGV[1] then
                return redis.call("del", KEYS[1])
            else
                return 0
            end
        `;

        return await this.redis.eval(script, 1, `lock:${lockKey}`, lockValue);
    }

    async withLock(lockKey, fn, ttl = 10000) {
        const lockValue = await this.acquire(lockKey, ttl);

        if (!lockValue) {
            throw new Error('Could not acquire lock');
        }

        try {
            return await fn();
        } finally {
            await this.release(lockKey, lockValue);
        }
    }
}

// Usage
const redis = createClient();
const lock = new DistributedLock(redis);

await lock.withLock('user:123:update', async () => {
    // Critical section - only one process can execute this
    const user = await db.users.findById(123);
    user.balance += 100;
    await db.users.update(user);
});

