template<typename T>
class CircularLinkedList {
private:
    struct Node {
        T data;
        Node* next;
        Node(T data) : data(data), next(nullptr) {}
    };

    Node* last;
    int size;

public:
    CircularLinkedList() : last(nullptr), size(0) {}

    ~CircularLinkedList() {
        if (!last) return;

        Node* current = last->next;
        while (current != last) {
            Node* temp = current;
            current = current->next;
            delete temp;
        }
        delete last;
    }

    void insertAtBeginning(T data) {
        Node* newNode = new Node(data);

        if (!last) {
            newNode->next = newNode;
            last = newNode;
        } else {
            newNode->next = last->next;
            last->next = newNode;
        }
        size++;
    }

    void insertAtEnd(T data) {
        insertAtBeginning(data);
        last = last->next;
    }

    void deleteNode(T key) {
        if (!last) return;

        Node* current = last->next;
        Node* prev = last;

        do {
            if (current->data == key) {
                if (current == last && current->next == last) {
                    delete current;
                    last = nullptr;
                } else {
                    prev->next = current->next;
                    if (current == last) {
                        last = prev;
                    }
                    delete current;
                }
                size--;
                return;
            }
            prev = current;
            current = current->next;
        } while (current != last->next);
    }

    bool search(T key) {
        if (!last) return false;

        Node* current = last->next;
        do {
            if (current->data == key) return true;
            current = current->next;
        } while (current != last->next);

        return false;
    }

    int getSize() const { return size; }
    bool isEmpty() const { return last == nullptr; }
};

import java.util.Random;

public class SkipList<T extends Comparable<T>> {
    private static class Node<T> {
        T value;
        Node<T>[] forward;

        @SuppressWarnings("unchecked")
        Node(T value, int level) {
            this.value = value;
            this.forward = new Node[level + 1];
        }
    }

    private static final int MAX_LEVEL = 16;
    private static final double P = 0.5;

    private Node<T> head;
    private int level;
    private Random random;
    private int size;

    public SkipList() {
        head = new Node<>(null, MAX_LEVEL);
        level = 0;
        random = new Random();
        size = 0;
    }

    private int randomLevel() {
        int lvl = 0;
        while (random.nextDouble() < P && lvl < MAX_LEVEL) {
            lvl++;
        }
        return lvl;
    }

    public void insert(T value) {
        @SuppressWarnings("unchecked")
        Node<T>[] update = new Node[MAX_LEVEL + 1];
        Node<T> current = head;

        for (int i = level; i >= 0; i--) {
            while (current.forward[i] != null && 
                   current.forward[i].value.compareTo(value) < 0) {
                current = current.forward[i];
            }
            update[i] = current;
        }

        int newLevel = randomLevel();

        if (newLevel > level) {
            for (int i = level + 1; i <= newLevel; i++) {
                update[i] = head;
            }
            level = newLevel;
        }

        Node<T> newNode = new Node<>(value, newLevel);
        for (int i = 0; i <= newLevel; i++) {
            newNode.forward[i] = update[i].forward[i];
            update[i].forward[i] = newNode;
        }
        size++;
    }

    public boolean search(T value) {
        Node<T> current = head;

        for (int i = level; i >= 0; i--) {
            while (current.forward[i] != null && 
                   current.forward[i].value.compareTo(value) < 0) {
                current = current.forward[i];
            }
        }

        current = current.forward[0];
        return current != null && current.value.equals(value);
    }

    public boolean delete(T value) {
        @SuppressWarnings("unchecked")
        Node<T>[] update = new Node[MAX_LEVEL + 1];
        Node<T> current = head;

        for (int i = level; i >= 0; i--) {
            while (current.forward[i] != null && 
                   current.forward[i].value.compareTo(value) < 0) {
                current = current.forward[i];
            }
            update[i] = current;
        }

        current = current.forward[0];

        if (current == null || !current.value.equals(value)) {
            return false;
        }

        for (int i = 0; i <= level; i++) {
            if (update[i].forward[i] != current) break;
            update[i].forward[i] = current.forward[i];
        }

        while (level > 0 && head.forward[level] == null) {
            level--;
        }

        size--;
        return true;
    }

    public int size() { return size; }
}

class UnionFind:
    """Union-Find (Disjoint Set Union) with path compression and union by rank"""

    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n  # Number of disjoint sets

    def find(self, x):
        """Find with path compression"""
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        """Union by rank"""
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return False

        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
        elif self.rank[root_x] > self.rank[root_y]:
            self.parent[root_y] = root_x
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += 1

        self.count -= 1
        return True

    def connected(self, x, y):
        """Check if x and y are in the same set"""
        return self.find(x) == self.find(y)

    def get_count(self):
        """Get number of disjoint sets"""
        return self.count

    def get_set_size(self, x):
        """Get size of set containing x"""
        root = self.find(x)
        return sum(1 for i in range(len(self.parent)) if self.find(i) == root)

class BloomFilter {
    constructor(size, numHashes) {
        this.size = size;
        this.numHashes = numHashes;
        this.bitArray = new Array(size).fill(false);
    }

    _hash(item, seed) {
        let hash = 0;
        const str = item.toString() + seed.toString();

        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash; // Convert to 32-bit integer
        }

        return Math.abs(hash) % this.size;
    }

    add(item) {
        for (let i = 0; i < this.numHashes; i++) {
            const index = this._hash(item, i);
            this.bitArray[index] = true;
        }
    }

    contains(item) {
        for (let i = 0; i < this.numHashes; i++) {
            const index = this._hash(item, i);
            if (!this.bitArray[index]) {
                return false; // Definitely not in set
            }
        }
        return true; // Probably in set
    }

    // Calculate optimal number of hash functions
    static optimalHashes(expectedItems, size) {
        return Math.ceil((size / expectedItems) * Math.log(2));
    }

    // Calculate optimal bit array size
    static optimalSize(expectedItems, falsePositiveRate) {
        return Math.ceil(
            -(expectedItems * Math.log(falsePositiveRate)) / (Math.log(2) ** 2)
        );
    }

    getFalsePositiveRate(numItems) {
        const k = this.numHashes;
        const m = this.size;
        const n = numItems;
        return Math.pow(1 - Math.exp(-k * n / m), k);
    }
}

