public class AdjacencyMatrix {
    private int[][] matrix;
    private int vertices;

    public AdjacencyMatrix(int vertices) {
        this.vertices = vertices;
        this.matrix = new int[vertices][vertices];
    }

    public void addEdge(int u, int v, int weight, boolean directed) {
        matrix[u][v] = weight;
        if (!directed) {
            matrix[v][u] = weight;
        }
    }

    public void addEdge(int u, int v, boolean directed) {
        addEdge(u, v, 1, directed);
    }

    public void removeEdge(int u, int v, boolean directed) {
        matrix[u][v] = 0;
        if (!directed) {
            matrix[v][u] = 0;
        }
    }

    public boolean hasEdge(int u, int v) {
        return matrix[u][v] != 0;
    }

    public int getWeight(int u, int v) {
        return matrix[u][v];
    }

    public int getDegree(int v) {
        int degree = 0;
        for (int i = 0; i < vertices; i++) {
            if (matrix[v][i] != 0) degree++;
        }
        return degree;
    }

    public int[] getNeighbors(int v) {
        int degree = getDegree(v);
        int[] neighbors = new int[degree];
        int index = 0;

        for (int i = 0; i < vertices; i++) {
            if (matrix[v][i] != 0) {
                neighbors[index++] = i;
            }
        }

        return neighbors;
    }

    public int getVertexCount() { return vertices; }
}

class Stack:
    """Stack implementation using dynamic array"""

    def __init__(self):
        self.items = []

    def push(self, item):
        """Push item onto stack - O(1) amortized"""
        self.items.append(item)

    def pop(self):
        """Pop and return top item - O(1)"""
        if self.is_empty():
            raise IndexError("Pop from empty stack")
        return self.items.pop()

    def peek(self):
        """Return top item without removing - O(1)"""
        if self.is_empty():
            raise IndexError("Peek from empty stack")
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

    def clear(self):
        self.items = []

class StackLinked:
    """Stack implementation using linked list"""

    class Node:
        def __init__(self, data):
            self.data = data
            self.next = None

    def __init__(self):
        self.top = None
        self._size = 0

    def push(self, item):
        """Push item onto stack - O(1)"""
        new_node = self.Node(item)
        new_node.next = self.top
        self.top = new_node
        self._size += 1

    def pop(self):
        """Pop and return top item - O(1)"""
        if self.is_empty():
            raise IndexError("Pop from empty stack")
        data = self.top.data
        self.top = self.top.next
        self._size -= 1
        return data

    def peek(self):
        if self.is_empty():
            raise IndexError("Peek from empty stack")
        return self.top.data

    def is_empty(self):
        return self.top is None

    def size(self):
        return self._size

class Queue {
    constructor() {
        this.items = [];
        this.frontIndex = 0;
    }

    enqueue(item) {
        this.items.push(item);
    }

    dequeue() {
        if (this.isEmpty()) {
            throw new Error('Queue is empty');
        }
        const item = this.items[this.frontIndex];
        this.frontIndex++;

        // Reset array when front index gets large
        if (this.frontIndex > 100 && this.frontIndex > this.items.length / 2) {
            this.items = this.items.slice(this.frontIndex);
            this.frontIndex = 0;
        }

        return item;
    }

    peek() {
        if (this.isEmpty()) {
            throw new Error('Queue is empty');
        }
        return this.items[this.frontIndex];
    }

    isEmpty() {
        return this.frontIndex >= this.items.length;
    }

    size() {
        return this.items.length - this.frontIndex;
    }

    clear() {
        this.items = [];
        this.frontIndex = 0;
    }
}

